import{_ as o,l,o as e,c as n,v as t,p as s,x as i,d as p,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"最优二叉搜索树","description":"","frontmatter":{"title":"最优二叉搜索树","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/optimal-bst.md","filePath":"cs/optimal-bst.md","lastUpdated":1789023840000}'),c={name:"cs/optimal-bst.md"};function _(u,a,m,T,S,f){const r=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="最优二叉搜索树" tabindex="-1">最优二叉搜索树 <a class="header-anchor" href="#最优二叉搜索树" aria-label="Permalink to &quot;最优二叉搜索树&quot;">​</a></h1><div class="epigraph"><p>关键字概率已知时，BST 的期望比较次数由区间 DP 最小化；四边形不等式把 $O(n^3)$ 收到 $O(n^2)$。</p><footer>—— 据 Knuth, Optimum Binary Search Trees, 1971；CLRS 第 15.5 节整理</footer></div><p>上一课<a href="/cs/sequence-alignment">序列比对</a>是两序列格图。本课一个有序关键字列 \\(k_1\\lt \\cdots\\lt k_n\\)，访问概率 \\(p_i\\)、空隙 \\(q_i\\)。缺口是最优 BST：根选 \\(k_r\\)，左右子树最优。主干<a href="/cs/interval-dp">区间 DP</a>已给矩阵链形状。本课把概率加权写清，Knuth 优化留一半给下一课矩阵链对照。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(e[i,j]\\) 为关键字 \\(i..j\\) 的最优期望代价。\\(w[i,j]\\) 为这段概率和（含空隙）。\\(e[i,j]=\\min_r(e[i,r-1]+e[r+1,j])+w[i,j]\\)。朴素 \\(O(n^3)\\)。Knuth：\\(opt[i,j-1]\\le opt[i,j]\\le opt[i+1][j]\\)，枚举 \\(r\\) 范围收缩，总 \\(O(n^2)\\)。</p><p>缺口是期望代价，不是 AVL 平衡（平衡不知 \\(p_i\\)）。</p><h3 id="不是哈夫曼" tabindex="-1">不是哈夫曼 <a class="header-anchor" href="#不是哈夫曼" aria-label="Permalink to &quot;不是哈夫曼&quot;">​</a></h3><p>哈夫曼是最优前缀码，字母不要求有序检索。BST 必须中序关键字有序。不要用哈夫曼当最优 BST。</p><p><span class="marginnote">Knuth 1971。CLRS 15.5。下一课矩阵链同一 Knuth 单调。Mehlhorn 近似最优 BST 点名。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>前缀和 \\(O(1)\\) 求 \\(w\\)。按长度填 \\(e\\)、\\(opt\\)。根方案存 \\(root[i,j]\\)。</p>',11)),(e(),s(d,null,{default:i(()=>[h(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E6%A6%82%E7%8E%87%20p%2C%20q%22%5D%20--%3E%20E%5B%22e%5Bi%2Cj%5D%20%E5%8C%BA%E9%97%B4%20DP%22%5D%0A%20%20E%20--%3E%20KNU%5B%22opt%20%E5%8D%95%E8%B0%83%20O(n%5E2)%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>静态概率；自适应 splay 另一模型。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>期望 = 子树期望 + 每次访问都经过根（故加 \\(w\\)）。最优子结构：左右仍是最优 BST。四边形来自 \\(w\\) 的性质。与矩阵链：切点含义不同，单调同类。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写动态最优 BST 猜想（splay 动态最优仍开）。不写熵界证明全文。后课默认：已知独立访问概率，最优 BST 区间 DP + Knuth。下一课矩阵链与 Knuth 优化收束本单元。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>最优 BST 是加权区间 DP。</li><li>Knuth 单调 \\(O(n^2)\\)。</li><li>不是哈夫曼，也不是平衡 BST。</li><li>出处：Knuth, 1971；CLRS 第 15.5 节。</li></ul>',7))])}const b=o(c,[["render",_]]);export{P as __pageData,b as default};
